bash $A/run_tests.sh provenance_and_callers tests/test_bypass_entry_trial.py tests/test_corner_corridor_shadow.py tests/test_corridor_roles.py tests/test_course_section.py tests/test_fragmented_follow.py tests/test_known_structure_policy.py tests/test_local_pursuit.py tests/test_long_preferred_prefix.py tests/test_occupancy_timing.py tests/test_r0_plus.py tests/test_r0_safety_contract.py tests/test_ray_wall_continuity.py tests/test_rounded_occupancy_candidate.py tests/test_short_boundary_prefix_probe.py tests/test_short_prefix_origin.py tests/test_structure_route_speed.py tests/test_swept_limit_batch.py tests/test_actor_tail_provenance.py tests/test_anchor_set_provenance.py tests/test_bypass_motion_pause_connection.py tests/test_bypass_relative_yield_provenance.py tests/test_continuous_prefix.py tests/test_forward_same_path_provenance.py tests/test_fresh_confirmation_provenance.py tests/test_g2_corridor_provenance.py tests/test_g2_directional_reference_provenance.py tests/test_g2_handoff_corridor_provenance.py tests/test_g2_handoff_provenance.py tests/test_g2_initial_reference_provenance.py tests/test_g2_preparation_hold_provenance.py tests/test_g2_signed_hold_provenance.py tests/test_measured_lane_preference_provenance.py tests/test_observed_lane_preference_provenance.py tests/test_rear_lane_keep_provenance.py tests/test_rolling_clearance_provenance.py tests/test_rotation_reobservation_provenance.py tests/test_same_scan_history_provenance.py tests/test_small_alignment_provenance.py tests/test_traffic_release_fringe.py; r3=$?
